import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const isolated = path.join(root, '.work/r32');
const checkpointPath = path.join(root, '.work/rrsi-journal-state-source-checkpoint.json');
const checkpoint = JSON.parse(fs.readFileSync(checkpointPath));
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path);
const { openJournalBoundaryFixture } = await import(pathToFileURL(path.join(isolated, 'packages/cli/__tests__/fixtures/evolution-journal-boundary.js')));
const helper = path.join(isolated, 'packages/cli/__tests__/fixtures/rrsi-journal-state-process.mjs');
const temp = fs.realpathSync.native(os.tmpdir());
const scenarios = [...['cold', 'cached', 'snapshot'].flatMap(branch => ['read', 'fifo', 'symlink', 'ending-mode'].map(mode => [branch, mode])), ['snapshot', 'parent-fifo']];
const results = [];
for (const [branch, mode] of scenarios) {
  const temporary = fs.mkdtempSync(path.join(temp, 'cc-journal-posix-'));
  try {
    const fixture = openJournalBoundaryFixture(temporary);
    if (branch === 'snapshot') fixture.ledger.checkpointState();
    const response = spawnSync(process.execPath, [helper, temporary, mode, branch], { encoding: 'utf8', timeout: 15_000 });
    assert.equal(response.error, undefined, `${branch}/${mode}: ${response.error}`);
    assert.equal(response.status, mode === 'read' ? 0 : 2, `${branch}/${mode}: ${response.stderr}\n${response.stdout}`);
    const value = JSON.parse(response.stdout);
    assert.equal(value.branch, branch); assert.equal(value.mode, mode);
    assert.equal(value.liveDescriptors, 0); assert.equal(value.rawReads, 0);
    assert.equal(value.preservedDigest, value.originalDigest); assert.equal(value.preservedInode, true);
    assert.equal(value.requestsWithinChunk, true);
    assert.equal(value.actualReadBytes, ['read', 'ending-mode'].includes(mode) ? value.expectedSize : 0);
    if (mode === 'read') {
      assert.equal(value.authenticatedSequence, 1); assert.equal(value.opens, 1); assert.equal(value.nonblocking, true);
      assert.deepEqual(value.eofProbe, { requested: 1, count: 0, position: value.expectedSize });
    } else {
      assert.equal(value.fired, true);
      assert.equal(value.code, ['ending-mode', 'parent-fifo', 'symlink'].includes(mode) ? 'CC_EVOLUTION_LEDGER_STORE_UNSAFE' : 'CC_EVOLUTION_LEDGER_CORRUPT', JSON.stringify(value));
      if (mode === 'fifo') { assert.equal(value.actualFifo, true); assert.equal(value.opens, 1); assert.equal(value.nonblocking, true); }
      if (mode === 'parent-fifo') {
        assert.equal(value.actualFifo, true); assert.equal(value.opens, 0);
        assert.equal(value.directoryFlags & fs.constants.O_NONBLOCK, fs.constants.O_NONBLOCK);
        assert.equal(value.directoryFlags & fs.constants.O_DIRECTORY, fs.constants.O_DIRECTORY);
      }
    }
    results.push({ passed: true, ...value });
    process.stdout.write(`${branch}/${mode}: passed\n`);
  } finally {
    assert.equal(path.dirname(temporary), temp);
    assert.ok(path.basename(temporary).startsWith('cc-journal-posix-'));
    fs.rmSync(temporary, { recursive: true, force: true });
  }
}
for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path);
const out = { recordedAt: new Date().toISOString(), platform: process.platform, nodeVersion: process.version,
  kernel: os.release(), passedScenarios: results.length, failures: 0,
  sourceCheckpointSha256: sha(checkpointPath), sourceDigests: checkpoint.sourceDigests,
  runnerSha256: sha(fileURLToPath(import.meta.url)), watchdogMs: 15_000,
  results, physicalPowerLossVerified: false, productionAuthority: false };
fs.writeFileSync(path.join(root, '.work/rrsi-journal-state-posix.json'), JSON.stringify(out, null, 2) + '\n');
process.stdout.write(JSON.stringify({ passedScenarios: results.length, failures: 0 }) + '\n');

