import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
const root = 'C:/code/chainlesschain', isolated = `${root}/.work/r32`;
const file = 'packages/cli/src/lib/evolution/evolution-ledger.js';
const legacyPath = `${isolated}/packages/cli/src/lib/evolution/rrsi-legacy-journal-test-only.js`;
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const baseline = JSON.parse(fs.readFileSync(`${root}/.work/rrsi-journal-state-baseline.json`));
const original = fs.readFileSync(`${root}/${file}`);
assert.equal(sha(original), baseline.rootBeforePropagation.find(entry => entry.path === file).sha256);
assert.ok(!fs.existsSync(legacyPath));
fs.writeFileSync(legacyPath, original, { flag: 'wx' });
const temporaryParent = fs.realpathSync.native(os.tmpdir());
const temporary = fs.mkdtempSync(path.join(temporaryParent, 'cc-journal-upgrade-'));
try {
  const { EvolutionLedger: Legacy } = await import(pathToFileURL(legacyPath));
  const { openJournalBoundaryFixture } = await import(pathToFileURL(`${isolated}/packages/cli/__tests__/fixtures/evolution-journal-boundary.js`));
  const fixture = openJournalBoundaryFixture(temporary, { Ledger: Legacy });
  fixture.ledger.checkpointState();
  const identityBytes = fs.readFileSync(fixture.files.identity), markerBytes = fs.readFileSync(fixture.files.marker);
  const identity = JSON.parse(identityBytes), legacyState = fixture.ledger.verify();
  const snapshotPath = path.join(fixture.ledger.authorityRootDir, fs.readdirSync(fixture.ledger.authorityRootDir).find(name => name.startsWith('state-snapshot-v1-')));
  const snapshotDigest = sha(fs.readFileSync(snapshotPath));
  fixture.policy.purposes.length = 0;
  const upgraded = fixture.open();
  assert.ok(fixture.policy.purposes.includes('state-snapshot'));
  assert.ok(!fixture.policy.purposes.includes('domain-event'));
  assert.deepEqual(upgraded.verify(), legacyState);
  assert.deepEqual(upgraded.verify(), legacyState);
  assert.deepEqual(fs.readFileSync(fixture.files.identity), identityBytes);
  assert.deepEqual(fs.readFileSync(fixture.files.marker), markerBytes);
  assert.equal(sha(fs.readFileSync(snapshotPath)), snapshotDigest);
  fixture.append('journal-upgraded-event', upgraded);
  assert.equal(upgraded.verify().sequence, 2);
  const back = fixture.open(Legacy);
  assert.equal(back.verify().sequence, 2);
  assert.deepEqual(fs.readFileSync(fixture.files.identity), identityBytes);
  assert.deepEqual(fs.readFileSync(fixture.files.marker), markerBytes);
  assert.equal(sha(fs.readFileSync(snapshotPath)), snapshotDigest);
  assert.equal(fixture.io.live.size, 0);
  const out = {
    recordedAt: new Date().toISOString(), platform: process.platform, nodeVersion: process.version,
    originalSourcePath: file, originalSourceSha256: sha(original), upgradedSourceSha256: sha(fs.readFileSync(`${isolated}/${file}`)),
    fixtureSourceSha256: sha(fs.readFileSync(`${isolated}/packages/cli/__tests__/fixtures/evolution-journal-boundary.js`)),
    procedure: 'Original section-34 ledger source bootstraps and appends a signed domain event and persistent snapshot in its original directory; new source reopens through signed snapshot and warm cache, appends another event; original source reopens the new prefix in the same directories',
    createdByOriginalSource: true, copiedToDifferentDirectory: false, originalSequence: 1, upgradedSequence: 2,
    originalSnapshotReadThroughExpectedBytes: true, oldReaderReopenedNewAppend: true,
    identityBytesUnchanged: true, storeMarkerBytesUnchanged: true, originalSnapshotBytesUnchanged: true,
    storeMarkerEntryDigest: identity.storeMarkerEntryDigest, storeBindingDigest: identity.storeBindingDigest,
    originalIdentitySha256: sha(identityBytes), originalStoreMarkerSha256: sha(markerBytes), originalSnapshotSha256: snapshotDigest,
    liveDescriptors: 0, physicalPowerLossVerified: false, productionAuthority: false,
  };
  fs.writeFileSync(`${root}/.work/rrsi-journal-state-legacy.json`, JSON.stringify(out, null, 2) + '\n');
  console.log(JSON.stringify({ oldSourceBootstrap: true, signedSnapshotAndCacheReopen: true, newAppendOldReopen: true, sequences: [1,2] }));
} finally {
  assert.equal(path.dirname(temporary), temporaryParent);
  assert.ok(path.basename(temporary).startsWith('cc-journal-upgrade-'));
  fs.rmSync(temporary, { recursive: true, force: true });
  assert.equal(path.resolve(legacyPath), path.resolve(`${isolated}/packages/cli/src/lib/evolution/rrsi-legacy-journal-test-only.js`));
  fs.rmSync(legacyPath, { force: true });
}
